-- Campanha Black Friday 2026 (aprovada pelo Jaderson em 22/11). Modelos 7.2 e 7.3 (padrao.py).
--  - 7.2-black-antecipado: cadastrados do Esquenta (serena_contatos com e-mail + esquenta_leads), qui 26/11 20h,
--    quando os descontos da Black ligam na Shopify.
--  - 7.3-black-friday: inscritos com consentimento (mesmo filtro do Esquenta), sem quem recebeu o 7.2. Ordem: compra mais
--    recente primeiro. 4.700 na sex 27/11 8h e o restante no sab 28/11 10h (limite do dia: 5.000, servico incluso).
-- Cancelar o que falta: update email_fila set status = 'pulado', motivo = 'campanha cancelada'
--   where ref = 'black-2026' and status = 'pendente';
create or replace function email_campanha_black() returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare n1 int; n2 int;
begin
  with esq as (
    select distinct on (x.em) x.em, x.nome from (
      select lower(trim(c.email)) as em, nullif(split_part(trim(coalesce(c.nome, '')), ' ', 1), '') as nome
        from esquenta_bf b join serena_contatos c on c.id = b.contato_id
      union all
      select lower(trim(l.email)), nullif(split_part(trim(coalesce(l.nome, '')), ' ', 1), '') from esquenta_leads l
    ) x
    where x.em ~ '^[a-z0-9._%+\-]+@[a-z0-9\-]+(\.[a-z0-9\-]+)*\.[a-z]{2,}$'
      and split_part(x.em, '@', 2) not in ('example.com', 'teste.com', 'test.com', 'teste-an.com', 'americanutrition.com')
      and not exists (select 1 from email_contatos e where e.email = x.em and e.status in ('descadastrado', 'reclamacao', 'bounce'))
    order by x.em, x.nome nulls last
  ), ins as (
    insert into email_fila (email, slug, fluxo, ref, enviar_em, prioridade, dados)
    select em, '7.2-black-antecipado', 'campanha', 'black-2026', email_dia(date '2026-11-26', 20), 2,
           jsonb_build_object('nome', coalesce(nome, ''))
      from esq
    on conflict do nothing returning 1)
  select count(*) into n1 from ins;

  with base as (
    select e.email, coalesce(e.ultimo_pedido_em, '1900-01-01'::timestamptz) ult, coalesce(e.pedidos, 0) ped
      from email_contatos e
     where e.status = 'inscrito' and e.shopify_consentimento = 'SUBSCRIBED'
       and email_corrigir(e.email) ~ '^[a-z0-9._%+\-]+@[a-z0-9\-]+(\.[a-z0-9\-]+)*\.[a-z]{2,}$'
       and split_part(email_corrigir(e.email), '@', 2) not in ('example.com', 'example.org', 'example.net', 'teste.com', 'test.com',
            'teste-an.com', 'dasda.com', 'asdas.com', 'americanutrition.com', 'marketplace.americanutrition.com', 'clientes.americanutrition.com')
       and not exists (select 1 from email_fila f where f.email = e.email and f.slug = '7.2-black-antecipado' and f.ref = 'black-2026')
  ), r as (
    select email, row_number() over (order by (ped > 0) desc, ult desc, email) rn from base
  ), ins as (
    insert into email_fila (email, slug, fluxo, ref, enviar_em, prioridade)
    select email, '7.3-black-friday', 'campanha', 'black-2026',
           case when rn <= 4700 then email_dia(date '2026-11-27', 8) else email_dia(date '2026-11-28', 10) end + (rn % 50) * interval '1 minute', 2
      from r
    on conflict do nothing returning 1)
  select count(*) into n2 from ins;
  return jsonb_build_object('antecipado', n1, 'black', n2);
end $$;
revoke all on function email_campanha_black() from public, anon, authenticated;
